begin;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email) values ('cf000000-0000-4000-8000-000000000088','00000000-0000-0000-0000-000000000000','authenticated','authenticated','intent-boundary@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"cf000000-0000-4000-8000-000000000088","role":"authenticated"}',true);
create temp table intent_ids(label text primary key,id uuid);
select public.create_currency('STALE','S',2);
insert into intent_ids values ('source',public.create_wallet('Intent source','cash','USD',0)),('target',public.create_wallet('Intent target','cash','USD',0));
insert into intent_ids select 'source-usd',default_balance_id from public.wallets where id=(select id from intent_ids where label='source');
insert into intent_ids select 'target-stale',id from public.wallet_balances where wallet_id=(select id from intent_ids where label='target') and currency='STALE';
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2,"STALE":2}')::text,true);
select public.update_currency('STALE','STALE','S',8);
select throws_ok($q$select * from public.record_balance_transfer('cf000000-0000-4000-8000-000000000089','2026-11-05',(select id from intent_ids where label='source-usd'),(select id from intent_ids where label='target-stale'),100,100,'Stale precision')$q$,'BT003','currency.intentConflict','stale destination denomination cannot acquire a first use');
select is((select first_used_at from public.currencies where code='STALE'),null::timestamptz,'rejected stale draft leaves automatic zero rows unused');
select throws_ok($q$insert into public.budgets(category_id,currency,starts_month,limit_minor) select id,'STALE','2026-11-01',100 from public.categories where kind='expense' and parent_id is null limit 1$q$,'BT003','currency.intentConflict','currency-only configuration validates the parsed unit');
select set_config('request.headers','{}',true);
select throws_ok($q$insert into public.budgets(category_id,currency,starts_month,limit_minor) select id,'STALE','2026-12-01',100 from public.categories where kind='expense' and parent_id is null limit 1$q$,'BT003','currency.intentConflict','omitted typed intent fails closed');

select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2,"STALE":2}')::text,true);
select throws_ok($q$select public.create_wallet('Stale opening','cash','STALE',100)$q$,'BT003','currency.intentConflict','typed opening is bound to its original unit');
select throws_ok($q$update public.profiles set salary_balance_id=(select id from intent_ids where label='target-stale'),salary_amount_minor=100 where user_id=auth.uid()$q$,'BT003','currency.intentConflict','first salary configuration rejects stale units');
select throws_ok($q$insert into public.fixed_expenses(name,balance_id,amount_minor,category_id,position) select 'Stale fixed',(select id from intent_ids where label='target-stale'),100,id,0 from public.categories where kind='expense' and parent_id is null order by position limit 1$q$,'BT003','currency.intentConflict','first fixed configuration rejects stale units');
select throws_ok($q$insert into public.installments(name,balance_id,total_minor,paid_before_minor,monthly_minor,category_id,position) select 'Stale installment',(select id from intent_ids where label='target-stale'),100,0,10,id,0 from public.categories where kind='expense' and parent_id is null order by position limit 1$q$,'BT003','currency.intentConflict','first installment configuration rejects stale units');
select throws_ok($q$select * from public.create_pending_payment(jsonb_build_object('requestId',gen_random_uuid(),'client','Acme','project','Stale pending','currency','STALE','totalMinor',100,'dueOn',null))$q$,'BT003','currency.intentConflict','currency-only pending configuration rejects stale units');
select throws_ok($q$select * from public.create_loan(jsonb_build_object('requestId',gen_random_uuid(),'name','Stale loan','direction','borrowed','principalMinor',100,'feeBps',0,'balanceId',(select id from intent_ids where label='target-stale'),'feeCategoryId',(select id from public.categories where kind='expense' and parent_id is null order by position limit 1),'openedOn','2026-11-05','creationMode','new','principalPaidBeforeMinor',0,'feePaidBeforeMinor',0))$q$,'BT003','currency.intentConflict','first loan and its generated disbursement reject stale units');
create function pg_temp.cash(p_cost text,p_payer uuid,p_change uuid default null) returns void language plpgsql as $$begin
 perform public.save_transaction(gen_random_uuid(),null,jsonb_build_object('kind','expense','occurredOn','2026-11-05','balanceId',p_payer,'amountMinor',100,'costCurrency',p_cost,'categoryId',(select id from public.categories where kind='expense' and parent_id is null order by position limit 1),'note',null),'[]',jsonb_build_object('tenderMinor',200,'changes',case when p_change is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('balanceId',p_change,'amountMinor',100)) end));
end $$;
select throws_ok($q$select pg_temp.cash('STALE',(select id from intent_ids where label='source-usd'))$q$,'BT003','currency.intentConflict','cash purchase cost has its own captured denomination');
select throws_ok($q$select pg_temp.cash('USD',(select id from intent_ids where label='target-stale'))$q$,'BT003','currency.intentConflict','cash tender has its own captured denomination');
select throws_ok($q$select pg_temp.cash('USD',(select id from intent_ids where label='source-usd'),(select id from intent_ids where label='target-stale'))$q$,'BT003','currency.intentConflict','cash change has its own captured denomination');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
select throws_ok($q$select pg_temp.cash('USD',(select id from intent_ids where label='source-usd'),(select id from intent_ids where label='target-stale'))$q$,'BT003','currency.intentConflict','omitting only the child unit fails atomically');
select is((select count(*) from public.transactions),0::bigint,'all rejected first-use families leave no partial parent/ledger rows');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2,"STALE":8}')::text,true);
select lives_ok($q$select * from public.record_balance_transfer('cf000000-0000-4000-8000-000000000090','2026-11-05',(select id from intent_ids where label='source-usd'),(select id from intent_ids where label='target-stale'),100,100,'Current units')$q$,'current expected units permit first use');
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2,"STALE":2}')::text,true);
select throws_ok($q$select * from public.record_balance_transfer(gen_random_uuid(),'2026-11-05',(select id from intent_ids where label='target-stale'),(select id from intent_ids where label='source-usd'),100,100,'Old draft')$q$,'BT003','currency.intentConflict','old source draft still rejects after another client marked the new precision used');
select public.create_currency('WRITEFIRST','W',2);
select set_config('request.headers',jsonb_build_object('x-budget-units','{"WRITEFIRST":2}')::text,true);
select lives_ok($q$insert into public.budgets(category_id,currency,starts_month,limit_minor) select id,'WRITEFIRST','2026-11-01',100 from public.categories where kind='expense' and parent_id is null limit 1$q$,'write-first configuration binds its denomination');
select throws_ok($q$select public.update_currency('WRITEFIRST','WRITEFIRST','W',8)$q$,'P0001','currency.used','write-first ordering permanently prevents reinterpretation');
select lives_ok($q$select public.update_currency('WRITEFIRST','WRITEFIRST','Symbol',2)$q$,'symbol-only edits preserve the unit');
select lives_ok($q$insert into public.budgets(category_id,currency,starts_month,limit_minor) select id,'WRITEFIRST','2026-12-01',100 from public.categories where kind='expense' and parent_id is null limit 1$q$,'symbol-only edit retains a valid typed denomination');
select set_config('request.headers','{"x-budget-units":"{\"USD\":9}"}',true);
select throws_ok($q$insert into public.budgets(category_id,currency,starts_month,limit_minor) select id,'USD','2026-12-01',100 from public.categories where kind='expense' and parent_id is null limit 1$q$,'BT003','currency.intentConflict','malformed unit precision fails closed');

select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":2}')::text,true);
insert into public.fixed_expenses(id,name,balance_id,amount_minor,category_id,position) select 'cf000000-0000-4000-8000-000000000091','Bound fixed',(select id from intent_ids where label='source-usd'),100,id,0 from public.categories where kind='expense' and parent_id is null order by position limit 1;
select set_config('request.headers',jsonb_build_object('x-budget-units','{"USD":8}')::text,true);
select throws_ok($q$select public.pay_fixed_expense('cf000000-0000-4000-8000-000000000091')$q$,'BT003','currency.intentConflict','implicit fixed generation still honors supplied stale intent');
select set_config('request.headers','{}',true);
select lives_ok($q$select public.pay_fixed_expense('cf000000-0000-4000-8000-000000000091')$q$,'server-bound fixed amount and exact balance permit genuinely implicit generation');
select throws_ok($q$insert into public.transactions(kind,occurred_on,balance_id,currency,amount_minor,tender_minor,source,fixed_expense_id,category_id) select 'expense','2026-11-05',balance_id,'USD',amount_minor,200,'fixed',id,category_id from public.fixed_expenses where id='cf000000-0000-4000-8000-000000000091'$q$,'BT003','currency.intentConflict','source tag cannot exempt a caller-typed tender from intent');
select * from finish();
rollback;
